"""CLI: python -m chartpack --out charts/

Writes four PNG charts plus a manifest.json containing, per PNG, the
sha256 of the file on disk and the exact aggregate numbers the chart
encodes. Output is fully deterministic (seeded data, stripped PNG
metadata): rerunning produces byte-identical files.
"""

from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path

import matplotlib

from . import charts, data

PNG_METADATA = {"Software": None}  # strip version string -> reproducible bytes


def sha256_file(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _round(x: float) -> float:
    return round(float(x), 6)


def compute_chart_numbers(df) -> dict:
    """Exact aggregates each chart encodes (rounded for stable JSON)."""
    store_totals = df.groupby("store")["revenue"].sum().reindex(data.STORES)
    shares = store_totals / store_totals.sum()

    per_day = df.groupby(["date", "is_weekend"], as_index=False)["revenue"].sum()
    weekday = per_day.loc[~per_day["is_weekend"], "revenue"]
    weekend = per_day.loc[per_day["is_weekend"], "revenue"]

    daily_total = df.groupby("date")["revenue"].sum().sort_index()
    cumulative_final = daily_total.cumsum().iloc[-1]

    return {
        "revenue_lines": {
            "days": int(df["date"].nunique()),
            "store_daily_mean": {
                s: _round(df[df["store"] == s]["revenue"].mean())
                for s in data.STORES
            },
        },
        "weekday_box": {
            "weekday_days": int(len(weekday)),
            "weekend_days": int(len(weekend)),
            "weekday_mean": _round(weekday.mean()),
            "weekend_mean": _round(weekend.mean()),
            "weekend_weekday_ratio": _round(
                weekend.mean() / weekday.mean()
            ),
            "weekday_median": _round(weekday.median()),
            "weekend_median": _round(weekend.median()),
        },
        "store_share_pie": {
            "store_totals": {s: _round(v) for s, v in store_totals.items()},
            "total_revenue": _round(store_totals.sum()),
            "store_shares": {s: _round(v) for s, v in shares.items()},
        },
        "cumulative_area": {
            "final_cumulative_revenue": _round(cumulative_final),
            "days": int(len(daily_total)),
        },
    }


def generate(out_dir: Path) -> dict:
    out_dir.mkdir(parents=True, exist_ok=True)
    df = data.generate_dataset()

    files_section: dict[str, dict] = {}
    for filename, builder in charts.CHART_BUILDERS.items():
        fig = builder(df)
        path = out_dir / filename
        fig.savefig(path, dpi=charts.DPI, metadata=dict(PNG_METADATA))
        matplotlib.pyplot.close(fig)
        files_section[filename] = {
            "sha256": sha256_file(path),
            "bytes": path.stat().st_size,
        }

    manifest = {
        "dataset": {
            "seed": data.SEED,
            "start_date": str(data.START_DATE.date()),
            "days": data.N_DAYS,
            "stores": list(data.STORES),
            "store_bases": data.STORE_BASES,
            "weekend_uplift": data.WEEKEND_UPLIFT,
            "noise_sd": data.NOISE_SD,
        },
        "files": files_section,
        "numbers": compute_chart_numbers(df),
    }
    manifest_path = out_dir / "manifest.json"
    manifest_path.write_text(json.dumps(manifest, indent=2, sort_keys=True))
    return manifest


def main(argv=None) -> None:
    parser = argparse.ArgumentParser(
        prog="python -m chartpack",
        description="Generate a pack of retail revenue charts + manifest.",
    )
    parser.add_argument("--out", default="charts/", type=Path,
                        help="Output directory (default: charts/)")
    args = parser.parse_args(argv)
    manifest = generate(args.out)
    print(f"Wrote {len(manifest['files'])} charts to {args.out}")
    for name in sorted(manifest["files"]):
        print(f"  {name}")


if __name__ == "__main__":
    main()

